@SpringBootApplication
public class EcommerceApplication {
    public static void main(String[] args) {
        SpringApplication.run(EcommerceApplication.class, args);
    }
}

@RestController
@RequestMapping("/api/products")
class ProductController {
    private final ProductRepository repository;

    ProductController(ProductRepository repository) {
        this.repository = repository;  // Auto-injected by Spring
    }

    @GetMapping
    List<Product> getAllProducts() {
        return repository.findAll();  // Returns JSON automatically
    }
}

record Product(Long id, String name, double price) {}

// Standard way (most common)
@SpringBootApplication
public class OrderServiceApplication {
    public static void main(String[] args) {
        SpringApplication.run(OrderServiceApplication.class, args);
    }
}

// Equivalent explicit form (same behavior)
@Configuration              // Makes this class a source of bean definitions
@EnableAutoConfiguration   // Triggers Spring Boot auto-config based on classpath
@ComponentScan             // Scans this package + sub-packages for @Component/@Service etc
public class OrderServiceApplication {
    public static void main(String[] args) {
        SpringApplication.run(OrderServiceApplication.class, args);
    }
}

// Customized version (when you need more control)
@SpringBootApplication(exclude = {DataSourceAutoConfiguration.class})
@ComponentScan(basePackages = {"com.company.orders", "com.company.shared"})
public class OrderServiceApplication {
    // Excludes database auto-config and scans additional packages
}

@SpringBootApplication
public class CustomerServiceApplication {
    public static void main(String[] args) {
        var context = SpringApplication.run(CustomerServiceApplication.class, args);
        // Application is fully started when this line executes
        System.out.println("Beans loaded: " + context.getBeanDefinitionCount());
    }
}

@Component
class StartupLogger implements CommandLineRunner {
    private final CustomerRepository repository;

    StartupLogger(CustomerRepository repository) {
        this.repository = repository;  // Injected before run() is called
    }

    @Override
    public void run(String... args) {
        // Runs AFTER all beans are created and web server starts
        System.out.println("App started with " + repository.count() + " customers");
    }
}
